export function getAppPages(locale: string) {
  const lang = (['en', 'tr', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja', 'ko', 'ar'] as Language[]).includes(locale as Language)
    ? (locale as Language)
    : 'en';
  return extractLocale(D, lang);
}

export type AppPages = ReturnType<typeof getAppPages>;
